async function STUFF_WORD(wd, slot) {
  let lv = RESERVE_LEXV, sv = 0, iv = RESERVE_INBUF, tn = 0;
  putb(lv, P_LEXWORDS, slot + 1);
  if (s16(slot) > s16(0)) {
    slot = slot - 1;
    lv = lv + ((2 * P_LEXSTART) + (2 * slot * P_LEXELEN));
    tn = 2 * (2 + getb(lv, 3));
    iv = iv + tn;
    lv = lv + 2;
  } else {
    tn = 0;
  }
  lv = lv + 2;
  sv = getb(iv, 0);
  putb(iv, 0, 0);
  putb(iv, 1, 0);
  dirOut(D_SCREEN_OFF);
  dirOut(D_TABLE_ON, iv);
  printB(wd);
  dirOut(D_TABLE_OFF);
  dirOut(D_SCREEN_ON);
  put(lv, 0, wd);
  putb(lv, 3, tn + 2);
  putb(lv, 2, get(iv, 0));
  tn = tn + 2 + get(iv, 0);
  putb(iv, 0, sv);
  putb(iv, 1, 0);
  putb(RESERVE_INBUF, 1, tn);
  g.RESERVE_PTR = 1;
  return true;
}

