async function STUFF(dest, src, max = 29) {
  let ctr = 1;
  putb(dest, 0, getb(src, 0));
  putb(dest, 1, getb(src, 1));
  dest = dest + (P_LEXSTART * 2);
  src = src + (P_LEXSTART * 2);
  for (;;) {
    put(dest, 0, get(src, 0));
    putb(dest, 2, getb(src, 2));
    putb(dest, 3, getb(src, 3));
    if (s16(ctr = ctr + 1) > s16(max)) {
      return true;
    }
    dest = dest + (2 * P_LEXELEN);
    src = src + (2 * P_LEXELEN);
  }
}

async function INBUF_STUFF(dest, src) {
  let cnt = 0;
  cnt = getb(src, 0) - 1;
  for (;;) {
    putb(dest, cnt, getb(src, cnt));
    if (s16(cnt = cnt - 1) < s16(0)) {
      return true;
    }
  }
}

