async function WINDOW(table, s1 = false, s2 = false, s3 = false, stline = 4) {
  let margin = 0, y = stline, i = 2, w_ = 0, lines = 0, str = 0, plines = 0, ct = 0, et = EXTRA_TEXT, sp = 0;
  put(et, 0, s1);
  put(et, 1, s2);
  put(et, 2, s3);
  lines = get(table, 0);
  plines = lines;
  w_ = get(table, 1);
  margin = div(g.WIDTH - w_, 2);
  splitWindow(lines + stline);
  setWindow(S_WINDOW);
  bufOut(false);
  highlight(H_INVERSE);
  cursorSet(y, margin);
  await PRINT_SPACES(w_);
  loop1: for (;;) {
    y = y + 1;
    cursorSet(y, margin);
    lines = lines - 1;
    if (lines == 0) {
      await PRINT_SPACES(w_);
      break loop1;
    }
    str = get(table, i);
    if (str == 0) {
      if (str = get(et, ct)) {
        sp = w_ - getb(str, 0);
        await PRINT_SPACES(div(sp, 2));
        await DUMP_LTABLE(str);
        ct = ct + 1;
        await PRINT_SPACES(sp - div(sp, 2));
      } else {
        await PRINT_SPACES(w_);
      }
    } else {
      printC(32);
      tell(S(str));
      printC(32);
    }
    i = i + 1;
  }
  highlight(H_NORMAL);
  bufOut(true);
  setWindow(S_TEXT);
  splitWindow(1);
  dirOut(D_SCREEN_OFF);
  i = 2;
  ct = 0;
  crlf();
  tell("[");
  loop2: for (;;) {
    plines = plines - 1;
    if (plines == 0) {
      break loop2;
    }
    str = get(table, i);
    if (!(str == 0)) {
      if (!(i == 2)) {
        printC(32);
      }
      tell(S(str));
    } else if (str = get(et, ct)) {
      ct = ct + 1;
      await PRINT_SPACES(div(w_ - getb(str, 0), 2));
      await DUMP_LTABLE(str);
    }
    if (plines == 1) {
      tell("]");
    }
    crlf();
    i = i + 1;
  }
  crlf();
  dirOut(D_SCREEN_ON);
  return true;
}

