async function V_QUIT(ask$ = true) {
  let scor = 0, wrd = 0;
  if (await WRONG_WINNER$()) {
    return FATAL_VALUE;
  }
  await V_SCORE();
  if (!(ask$ == 0)) {
    crlf();
    await SAY_SURE();
    tell("leave the story now?");
    if (await YES$()) {
      crlf();
      await quit();
    } else {
      tell("\n[Continuing.]\n");
    }
  } else {
    loop1: for (;;) {
      tell("\nRESTORE, RESTART, or QUIT?\n>>");
      await read(P_INBUF, P_LEXV);
      if ((getb(P_LEXV, P_LEXWORDS) == 0) || eq(wrd = get(P_LEXV, P_LEXSTART), W.QUIT, W.Q)) {
        await quit();
      } else if (wrd == W.RESTART) {
        await restart();
        (await FAILED("RESTART"));
        continue loop1;
      } else if (wrd == W.RESTORE) {
        if (!(await DO_RESTORE())) {
          continue loop1;
        }
      } else {
        await quit();
      }
      break loop1;
    }
  }
  return true;
}

