async function SAID_YES$(str, p_ = false) {
  let word = 0;
  for (;;) {
    tell("\n");
    if (!p_) {
      tell(">>");
    } else {
      tell(S(p_));
    }
    putb(YES_LEXV, 0, 4);
    await read(YES_INBUF, YES_LEXV);
    word = get(YES_LEXV, P_LEXSTART);
    if (getb(YES_LEXV, P_LEXWORDS) == 0) {
    } else if (!(word == 0)) {
      if (await YES_USED$(word)) {
        return true;
      } else if (await NO_USED$(word)) {
        return false;
      }
    }
    if (!(str == 0)) {
      tell(S(str), "\n");
    } else {
      return false;
    }
  }
}

async function YES_USED$(word) {
  if ((word == W.Y || word == W.YES || word == W.YUP) || (word == W.OKAY || word == W.OK || word == W.AYE) || (word == W.SURE || word == W.AFFIRMATIVE || word == W.POSITIVE) || (word == W.YEAH)) {
    return true;
  } else {
    return false;
  }
}

async function NO_USED$(word) {
  if ((word == W.N || word == W.NO || word == W.NOPE) || (word == W.NAY || word == W.NAW || word == W.NEGATIVE)) {
    return true;
  } else {
    return false;
  }
}

