async function SAY_SCORE_UPDATE(which, cr, down$ = false) {
  if (g.DO_SCORE$ == 2) {
    return false;
  } else {
    if (!(cr == 0)) {
      crlf();
    }
    highlight(H_BOLD);
    tell("[Your ", S(which), " just went ");
    if (!(down$ == 0)) {
      tell("down");
    } else {
      tell("up");
    }
    tell(".]");
    highlight(H_NORMAL);
    crlf();
    sound(1);
    return true;
  }
}

async function UPDATE_BP(factor = 1, cr = true, decay$ = false) {
  let systolic = (await GET_SYSTOLIC()), diastolic = (g.BP & 255), already_normal$ = false;
  if (factor == 0) {
    return false;
  }
  g.BP_DELAY = DELAY_FACTOR;
  if ((s16(systolic) >= s16(119)) && (s16(systolic) <= s16(121))) {
    already_normal$ = true;
  }
  if ((s16(factor) > s16(0)) && (s16(g.LAST_BP_CHANGE) > s16(0))) {
    factor = factor + g.LAST_BP_CHANGE;
  }
  g.LAST_BP_CHANGE = factor;
  if (s16(systolic = systolic + factor) > s16(255)) {
    systolic = 250;
  }
  diastolic = 80 + div(systolic - 120, 2);
  g.BP = (systolic * SYSTOLIC_SHIFT) | diastolic;
  if (decay$) {
    if ((s16(systolic) >= s16(119)) && (s16(systolic) <= s16(121))) {
      g.BP = (120 * SYSTOLIC_SHIFT) | 80;
      if (!already_normal$) {
        if (!(cr == 0)) {
          crlf();
        }
        tell("You're beginning to feel normal again.");
        if (!(cr == 0)) {
          crlf();
        }
      }
      return true;
    } else {
      return false;
    }
  } else if ((s16(systolic) > s16(230)) && (s16(diastolic) > s16(130))) {
    if (!(cr == 0)) {
      crlf();
    }
    tell("Your blood pressure soars to ");
    await SAY_BP();
    tell(", causing a small vessel in your brain to rupture. You sink into coma and die without pain.");
    await JIGS_UP();
    return true;
  } else if (s16(systolic) <= s16(96)) {
    if (!(cr == 0)) {
      crlf();
    }
    tell("Your blood pressure drops to a level too low to sustain higher brain activities, and you fall asleep.\n");
    await CARRIAGE_RETURNS();
    g.BP = (120 * SYSTOLIC_SHIFT) | 80;
    tell("You wake up refreshed and invigorated", S(PCR));
    await V_LOOK();
    return true;
  }
  return (await SAY_SCORE_UPDATE("blood pressure", cr, s16(factor) < s16(0) ? true : false));
}

