async function TELL_TIME() {
  let h = 0, pm$ = false;
  tell(S(get(DAY_TABLE, get(DAY_TABLE, 0))), "day, ");
  if (s16(g.HOURS) > s16(11)) {
    pm$ = true;
  }
  if (s16(g.HOURS) > s16(12)) {
    h = g.HOURS - 12;
  } else if (g.HOURS == 0) {
    h = 12;
  } else {
    h = g.HOURS;
  }
  tell(N(h), ":");
  if (s16(g.MINUTES) < s16(10)) {
    tell("0");
  }
  tell(N(g.MINUTES));
  if (!(pm$ == 0)) {
    tell(" pm");
  } else {
    tell(" am");
  }
  return true;
}

