async function V_OPEN() {
  let tbl = 0, foo = 0;
  foo = getProp(g.PRSO, P.MAIL_LETTER);
  if (hasFlag(g.PRSO, LIVING) || hasFlag(g.PRSO, PERSON)) {
    return await PERFORM(V.LOOK_INSIDE, g.PRSO);
  } else if (!(foo == 0)) {
    if (!(loc(g.PRSO) == PLAYER)) {
      await PERFORM(V.TAKE, g.PRSO);
    }
    if (loc(g.PRSO) == PLAYER) {
      putProp(g.PRSO, P.MAIL_LETTER, false);
      await PERFORM(V.OPEN, g.PRSO);
      putProp(g.PRSO, P.MAIL_LETTER, foo);
    }
    return true;
  } else if (!(hasFlag(g.PRSO, OPENABLE))) {
    await CANT_OPEN_PRSO();
    return true;
  } else if (hasFlag(g.PRSO, OPENED)) {
    await ALREADY_OPEN();
    return true;
  } else if (hasFlag(g.PRSO, LOCKED)) {
    await CTHE_PRINT();
    tell(" seems to be locked.\n");
    return true;
  } else {
    setFlag(g.PRSO, OPENED);
    tbl = getPropAddr(g.PRSO, P.ADJECTIVE);
    if (!(tbl == 0) && eq(get(tbl, 0), W.CLOSED)) {
      put(tbl, 0, W.OPENED);
      put(tbl, 1, W.OPEN);
    }
    (await YOU_FROB(false, "open"));
    await THE_PRINT();
    tell(S(PERIOD));
    if (hasFlag(g.PRSO, CONTAINER)) {
      if (!(first(g.PRSO)) || hasFlag(g.PRSO, TRANSPARENT)) {
      } else {
        crlf();
        tell(S(YOU_SEE));
        await PRINT_CONTENTS(g.PRSO);
        tell(" inside.\n");
      }
    }
    return true;
  }
}

