async function FALLS(saytheo = false) {
  let obj = g.PRSO;
  if (g.HERE == IN_COMPLEX) {
    return await HANDLE_COMPLEX_DROP(obj);
  } else if (g.HERE == BANK) {
    return await HANDLE_BANK_DROP(obj);
  }
  if (saytheo) {
    await CTHE_PRINT();
    tell(" ");
  }
  if (g.HERE == IN_TREE) {
    move(obj, IN_POT);
    g.P_IT_OBJECT = NOT_HERE_OBJECT;
    tell("falls out of sight.\n");
    return true;
  } else if (g.HERE == OUTSIDE_PLANE || g.HERE == IN_AIR) {
    remove(obj);
    g.P_IT_OBJECT = NOT_HERE_OBJECT;
    tell("disappears below you.\n");
    return true;
  } else if (g.HERE == AIRPORT_CONCOURSE || g.HERE == AIRPORT_ENTRANCE || g.HERE == AIRLINE_DESK) {
    move(obj, LANDF);
    g.P_IT_OBJECT = NOT_HERE_OBJECT;
    tell("disappears amid the teeming crowd.\n");
    return true;
  } else if (g.HERE == PILLAR_A || g.HERE == PILLAR_B) {
    move(obj, LANDF);
    g.P_IT_OBJECT = NOT_HERE_OBJECT;
    tell("falls out of sight.\n");
    return true;
  } else if (await BOTTOM_DUCT$()) {
    if (hasFlag(GRATE, OPENED)) {
      move(obj, LANDF);
      g.P_IT_OBJECT = NOT_HERE_OBJECT;
      tell("falls through the open grate and disappears.\n");
    } else {
      move(obj, GRATE);
      tell("lands on the grate.\n");
    }
    return true;
  } else if (g.HERE == DUCT || g.HERE == TOWER_DUCT) {
    if (hasFlag(GRATE, OPENED)) {
      move(obj, LANDF);
    } else {
      move(obj, GRATE);
    }
    g.P_IT_OBJECT = NOT_HERE_OBJECT;
    tell("slides down into ");
    await THE_PRINT(DUCT);
    tell(" and disappears.\n");
    return true;
  } else {
    move(obj, g.HERE);
    tell("land");
    if (!(hasFlag(obj, PLURAL))) {
      tell("s");
    }
    tell(" at your feet.\n");
    return true;
  }
}

