async function LOOK_INTDIR$() {
  let ptr = 0, tbl = 0, x = 0;
  if (!(g.PRSO == INTDIR)) {
    return false;
  } else {
    x = get(DIRTABLES, 0);
    ptr = get(x, 0);
    ptr = ptr - 1;
    x = x + 2;
    tbl = get(DIRTABLES, 1);
    loop1: for (;;) {
      if (g.P_DIRECTION == get(x, ptr)) {
        x = getProp(g.HERE, get(tbl, ptr));
        if (!(x == 0)) {
          await SEE_DIR(x);
          return true;
        }
        break loop1;
      } else if (s16(ptr = ptr - 1) < s16(0)) {
        break loop1;
      }
    }
  }
  x = getProp(g.HERE, P.SEE_ALL);
  if (!(x == 0)) {
    await SEE_DIR(x);
    return true;
  }
  await NOTHING_INTERESTING();
  tell(" in that direction", S(PERIOD));
  return true;
}

