async function EMPTY_PRSO(dest) {
  let obj = 0, nxt = 0, x = 0;
  obj = first(g.PRSO);
  if (obj == 0) {
    tell("There's nothing ");
    if (hasFlag(g.PRSO, SURFACE)) {
      tell("on ");
    } else {
      tell("in ");
    }
    await THE_PRINT();
    tell(S(PERIOD));
  } else {
    g.P_MULT$ = true;
    loop1: for (;;) {
      nxt = next(obj);
      await CTHE_PRINT(obj);
      tell(": ");
      if (dest == PLAYER) {
        x = await PERFORM(V.TAKE, obj, g.PRSO);
        if (x == FATAL_VALUE) {
          break loop1;
        }
      } else if (dest == GROUND) {
        if (hasFlag(g.PRSO, PLURAL)) {
          tell("They ");
        } else {
          tell("It ");
        }
        await FALLS();
      } else if (s16(((await WEIGHT(dest)) + (await WEIGHT(obj))) - getProp(dest, P.SIZE)) > s16(getProp(dest, P.CAPACITY))) {
        tell("There isn't enough room ");
        if (hasFlag(dest, CONTAINER)) {
          tell("in ");
        } else {
          tell("on ");
        }
        await THE_PRINT(dest);
        tell(S(PERIOD));
      } else {
        move(obj, dest);
        tell("Done.\n");
      }
      obj = nxt;
      if (obj == 0) {
        break loop1;
      }
    }
    g.P_MULT$ = false;
  }
  return true;
}

