async function V_TAKE_OFF(get_ = false) {
  let obj = 0;
  if ((g.PRSO == ROOMS) && !get_) {
    obj = first(g.WINNER);
    loop1: for (;;) {
      if (obj == 0) {
        await V_WALK_AROUND();
        return true;
      } else if (hasFlag(obj, WORN)) {
        break loop1;
      }
      obj = next(obj);
    }
    tell("[");
    await THE_PRINT(obj);
    tell(S(BRACKET));
    obj = await PERFORM(V.TAKE_OFF, obj);
  } else if (g.PRSO == CLOTHES || g.PRSO == FEET) {
    await INAPPROPRIATE();
  } else if (hasFlag(g.PRSO, PLACE)) {
    await NOT_IN();
  } else if (hasFlag(g.PRSO, TAKEABLE)) {
    if ((loc(g.PRSO) == g.WINNER) && hasFlag(g.PRSO, WORN)) {
      clearFlag(g.PRSO, WORN);
      tell("You take off ");
      await THE_PRINT();
      tell(S(PERIOD));
    } else if (loc(g.PRSO) == g.WINNER) {
      await PERFORM(V.DROP, g.PRSO);
    } else {
      await PERFORM(V.TAKE, g.PRSO);
    }
  } else if (hasFlag(g.PRSO, VEHBIT)) {
    await PERFORM(V.EXIT, g.PRSO);
  } else {
    await IMPOSSIBLE();
  }
  return true;
}

