async function PERFORM_WALK_TO(room) {
  let tt = 0, wt = WALKING_TABLE, ct = 0, cf = 0, troom = 0, oh = 0;
  cf = getProp(room, P.ENTER_FROM);
  if (!cf || (g.HERE != get(cf, 1))) {
    loop1: for (;;) {
      if (!((tt = getProp(g.HERE, P.EXIT_TO)) == 0)) {
        await GOTO(tt);
        if (tt != g.HERE) {
          return false;
        }
        if (g.HERE == room || g.HERE == cf) {
          return true;
        }
      } else {
        break loop1;
      }
    }
  }
  troom = room;
  loop2: for (;;) {
    if (!((tt = getProp(troom, P.ENTER_FROM)) == 0)) {
      put(wt, ct, get(tt, 0));
      put(wt, ct = ct + 1, troom = get(tt, 1));
      ct = ct + 1;
      if (g.HERE == get(tt, 1)) {
        break loop2;
      }
    } else {
      break loop2;
    }
  }
  if (s16(ct) > s16(0)) {
    if (g.HERE != (cf = get(wt, ct = ct - 1))) {
      await GOTO(cf);
    }
    oh = 0;
    for (;;) {
      oh = g.HERE;
      await DO_WALK(get(wt, ct = ct - 1));
      if (oh == g.HERE) {
        return true;
      }
      if (s16(ct = ct - 1) <= s16(0)) {
        return true;
      }
    }
  } else {
    return await GOTO(room);
  }
}

