async function ITAKE(vb = true) {
  let l = 0, ml = 0, de = 0;
  if ((g.PRSO == 0) || (loc(g.PRSO) == 0)) {
    await CANT_SEE_ANY();
    return false;
  }
  l = loc(g.PRSO);
  await THIS_IS_IT(g.PRSO);
  if (!(hasFlag(g.PRSO, TAKEABLE))) {
    if (!(vb == 0)) {
      await IMPOSSIBLE();
    }
    return false;
  } else if (hasFlag(l, CONTAINER) && hasFlag(l, OPENABLE) && !(hasFlag(l, OPENED))) {
    if (!(vb == 0)) {
      (await YOUD_HAVE_TO("open", l));
    }
    return false;
  } else if (!(loc(l) == g.WINNER) && (s16((await WEIGHT(g.PRSO)) + (await WEIGHT(g.WINNER))) > s16(LOAD_ALLOWED))) {
    if (!(vb == 0)) {
      if (first(g.WINNER)) {
        tell("Your load is");
      } else {
        await CTHE_PRINT();
        tell(" is");
      }
      tell(" too heavy.\n");
    }
    return false;
  } else if (s16(await CCOUNT(g.WINNER)) > s16(FUMBLE_NUMBER)) {
    if (!(vb == 0)) {
      tell("You're holding too much already.\n");
    }
    return false;
  } else {
    ml = getProp(g.PRSO, P.MAIL_LETTER);
    if (s16(ml) < s16(0)) {
      ml = 0 - ml;
      if (!(hasFlag(g.PRSO, TOUCHED))) {
        l = loc(g.PRSO);
        setFlag(g.PRSO, TOUCHED);
        de = get(PRINTR_TABLE, ml - 1);
        put(de, 0, get(RPRINTR_TABLE, g.MAIL_COUNT));
        g.MAIL_COUNT = g.MAIL_COUNT + 1;
        g.PRSO = await PICK_NEXT(MAILING_LIST);
        putProp(g.PRSO, P.MAIL_LETTER, ml);
        put(getPropAddr(g.PRSO, P.SYNONYM), 0, ml == 1 ? W.B : (ml == 2 ? W.C : (ml == 3 ? W.D : W.E)));
        tell("Most of the mail is rather useless, not even worth picking up. ");
        if (g.PRSO != ENVELOPE) {
          tell("You do find ");
          await PRINTA(g.PRSO);
          tell(", though.\n");
        } else {
          await SETUP_CHECK(l);
          tell("Amid the junk, you find ");
          await PRINTA(g.PRSO);
          tell(" and ");
          await PRINTA(BOSS_CHECK);
          tell(". You regretfully leave ");
          await THE_PRINT(BOSS_CHECK);
          tell(" behind, and take ");
          await THE_PRINT(g.PRSO);
          tell(S(PERIOD));
        }
        await UPDATE_SCORE(1);
        l = false;
        g.P_IT_OBJECT = g.PRSO;
        g.P_MULT$ = true;
      } else {
        tell("You probably shouldn't push your luck in illegally looking at other people's mail.\n");
        return false;
      }
    }
    setFlag(g.PRSO, TOUCHED);
    clearFlag(g.PRSO, NODESC);
    clearFlag(g.PRSO, NOALL);
    move(g.PRSO, g.WINNER);
    return l;
  }
}

async function CCOUNT(thing) {
  let obj = 0, cnt = 0;
  obj = first(thing);
  loop1: for (;;) {
    if (obj == 0) {
      break loop1;
    } else if (!(hasFlag(obj, WORN)) && !(obj == POCKET)) {
      cnt = cnt + 1;
    }
    obj = next(obj);
  }
  return cnt;
}

async function WEIGHT(thing) {
  let obj = 0, wt = 0;
  obj = first(thing);
  loop1: for (;;) {
    if (obj == 0) {
      break loop1;
    } else if (!(obj == POCKET)) {
      if ((thing == g.WINNER) && hasFlag(obj, WORN)) {
        wt = wt + 1;
      } else {
        wt = wt + (await WEIGHT(obj));
      }
    }
    obj = next(obj);
  }
  obj = getProp(thing, P.SIZE);
  if (!(obj == 0)) {
    wt = wt + obj;
  }
  return wt;
}

