async function START_CAPS() {
  dirOut(D_SCREEN_OFF);
  return dirOut(D_TABLE_ON, SL_TABLE);
}

async function END_CAPS(allwords$ = false) {
  let cnt = 2, len = 0, x = 0, lc = 0;
  dirOut(D_TABLE_OFF);
  dirOut(D_SCREEN_ON);
  len = get(SL_TABLE, 0);
  len = len + 1;
  put(SL_TABLE, 0, 0);
  if (len == 1) {
    return true;
  }
  lc = 32;
  for (;;) {
    x = getb(SL_TABLE, cnt);
    if ((s16(x) >= s16(97)) && (s16(x) <= s16(122))) {
      if ((cnt == 2) || (!(allwords$ == 0) && (lc == 32))) {
        x = x - 32;
      }
    }
    printC(x);
    lc = x;
    if (s16(cnt = cnt + 1) > s16(len)) {
      return true;
    }
  }
}

async function IN_CAPS(x) {
  await START_CAPS();
  await DO_PRINT_WORD(x);
  return await END_CAPS();
}

