async function GIVE_TO_CLERK(give_or_show) {
  let obj = g.PRSO;
  if (obj == LEAFLET) {
    await CTHE_PRINT(CLERK);
    tell(" glances at ");
    await THE_PRINT();
    tell(". \"That's not in stock yet. Come back next week.\"\n");
    return true;
  } else if (!(hasFlag(SOFTWARE, TOUCHED))) {
    if (obj == ADVENTURE) {
      if (give_or_show) {
        await CTHE_PRINT(CLERK);
        tell(" takes ");
        await THE_PRINT(ADVENTURE);
        tell(", looks at it lovingly and gives it back to you. ");
      } else {
        await CTHE_PRINT(CLERK);
        tell(" looks lovingly at ");
        await THE_PRINT(ADVENTURE);
        tell(". ");
      }
      setFlag(SOFTWARE, TOUCHED);
      return await SEEN_SOFTWARE$(false);
    } else if (hasFlag(obj, PROGRAM)) {
      await CTHE_PRINT(CLERK);
      if (give_or_show) {
        tell(" refuses your offer.");
      } else {
        tell(" seems uninterested.");
      }
      tell(" \"Typical of the junk on the market,\" he sneers.\n");
      return true;
    } else if (give_or_show) {
      await CTHE_PRINT(CLERK);
      tell(" refuses your offer.\n");
      return true;
    } else {
      await CTHE_PRINT(CLERK);
      tell(" doesn't seem interested.\n");
      return true;
    }
  } else {
    if (obj == ADVENTURE) {
      if (give_or_show) {
        await CTHE_PRINT(CLERK);
        tell(" takes ");
        await THE_PRINT(ADVENTURE);
        tell(" from you. ");
      } else {
        await CTHE_PRINT(CLERK);
        tell(" yanks ");
        await THE_PRINT(ADVENTURE);
        tell(" out of your hands. ");
      }
      setFlag(SOFTWARE, SEEN);
      move(obj, CLERK);
      move(RECIPE, PLAYER);
      putb(33976, 38, true);
      await DEQUEUE(I_CLERK_TRADE.id);
      setFlag(RECIPE, SEEN);
      if (hasFlag(SOFTWARE, SEEN)) {
        tell("\"I ");
        (await ITALICIZE("knew"));
        if (g.TURNED_DOWN_CLERK$) {
          tell(" you'd change your mind. I can always tell");
        } else {
          tell(" you were into that stuff");
        }
        tell(",\" he chortles. ");
      }
      tell("He tosses you ");
      await THE_PRINT(RECIPE);
      tell(". \"Here, have fun.\"\n");
      await UPDATE_SCORE(1);
      return true;
    } else if (hasFlag(obj, PROGRAM)) {
      await CTHE_PRINT(CLERK);
      tell(" glances at ");
      await THE_PRINT(obj);
      tell(". \"I already have that one.\"\n");
      return true;
    } else if (obj == BEEZER || obj == EXCESS) {
      tell("\"Are you crazy? This cart is hot!\"\n");
      return true;
    } else if (obj == CHECK) {
      tell("\"I can't do anything with that!\"\n");
      return true;
    } else {
      await CTHE_PRINT(CLERK);
      tell(" refuses your offer.\n");
      return true;
    }
  }
}

