async function PARSE_RANDOM_LOC(adj, nam, stuff) {
  let obj = 0, tbl = 0;
  let $1;
  if ((adj == W.INTNUM) && (nam == W.ZZSTREET)) {
    obj = first(ROOMS);
    loop1: for (;;) {
      if (g.P_NUMBER == getProp(obj, P.STADDR)) {
        break loop1;
      }
      if (!(obj = next(obj))) {
        break loop1;
      }
    }
    if (!obj) {
      tell("[", N(g.P_NUMBER), " ");
      $1 = await SHOW_FIELD(STREET_NAME);
      tell(S($1));
      tell(" isn't a valid address.]\n");
    }
    return obj;
  } else if (await THIS_IT$(YOUR_HOUSE)) {
    return YOUR_HOUSE;
  } else if ((nam == W.ROOM) && (!adj || (adj == W.THIS))) {
    if (hasFlag(g.HERE, INDOORS)) {
      return g.HERE;
    } else {
      tell("You aren't in a room.\n");
      return FATAL_VALUE;
    }
  } else {
    obj = first(ROOMS);
    tbl = 0;
    loop2: for (;;) {
      if ((tbl = getPropAddr(obj, P.SYNONYM)) && inTable(nam, tbl, div(propSize(tbl), 2)) && (!adj || ((tbl = getPropAddr(obj, P.ADJECTIVE)) && inTable(adj, tbl, div(propSize(tbl), 2))))) {
        break loop2;
      }
      if (!(obj = next(obj))) {
        break loop2;
      }
    }
    return obj;
  }
}

