async function JIGS_UP(end$ = false) {
  let word = 0;
  if (!end$) {
    g.BP = 0;
    g.HERE = DEATH;
    move(PLAYER, g.HERE);
    tell("\n\n");
    await DISPLAY_PLACE();
    await DISPLAY_BP();
    g.WINNER = PLAYER;
    await V_LOOK();
    crlf();
  }
  await V_SCORE();
  tell("\nDo you want to RESTORE a previously saved position, RESTART from the beginning, or QUIT?\n\n");
  for (;;) {
    tell("[Type RESTORE, RESTART or QUIT.] >");
    putb(YES_LEXV, 0, 4);
    await read(YES_INBUF, YES_LEXV);
    word = get(YES_LEXV, P_LEXSTART);
    if (getb(YES_LEXV, P_LEXWORDS) == 0) {
    } else if (word == W.RESTORE) {
      await V_RESTORE();
    } else if (word == W.RESTART) {
      await restart();
      (await FAILED("RESTART"));
    } else if (word == W.QUIT || word == W.Q) {
      crlf();
      await quit();
    }
  }
  return true;
}

