async function CHECK_TAKE_FROM(tbl, len) {
  let pi = 0, pil = 0, best$ = false, obj = 0;
  if (isVerb(V.TAKE) && (g.P_PHR == 0) && !(get(P_ITBL, P_NC2) == 0)) {
    pi = g.P_PRSI + 2;
    pil = get(g.P_PRSI, 0);
    obj = 0;
    loop1: for (;;) {
      if (inTable(loc(obj = get(tbl, len = len - 1)), pi, pil)) {
        if (best$) {
          return false;
        }
        best$ = obj;
      }
      if (s16(len) <= s16(0)) {
        break loop1;
      }
    }
    return best$;
  } else {
    return false;
  }
}

async function GENERIC_SOFTWARE_F(tbl) {
  let len = 0, best$ = false, obj = 0;
  len = get(tbl, 0);
  tbl = tbl + 2;
  if (best$ = await CHECK_TAKE_FROM(tbl, len)) {
    return best$;
  } else if (inTable(g.P_IT_OBJECT, tbl, len)) {
    return g.P_IT_OBJECT;
  } else if (inTable(g.P_THEM_OBJECT, tbl, len)) {
    return g.P_THEM_OBJECT;
  } else if ((await NOUN_USED$(W.SOFTWARE)) && inTable(SOFTWARE, tbl, len)) {
    return SOFTWARE;
  } else {
    len = len - 1;
    obj = 0;
    loop1: for (;;) {
      if (loc(obj = get(tbl, len)) == PLAYER) {
        if (!best$ || !(loc(best$) == PLAYER)) {
          best$ = obj;
        } else {
          best$ = false;
          break loop1;
        }
      } else if (!(loc(obj) == 0) && (loc(loc(obj)) == PLAYER)) {
        if (!best$) {
          best$ = obj;
        } else if (!(loc(best$) == PLAYER)) {
          best$ = false;
        }
      }
      if (s16(len = len - 1) < s16(0)) {
        break loop1;
      }
    }
    return best$;
  }
}

