async function GET_CABWORD(tbl = false, alpha = true, otbl = false) {
  let offs = 0, dptr = 1, sptr = 0, word = 0, len = 0, x = 0, lexw = 0, word2 = false;
  loop1: for (;;) {
    tell("\n>>");
    await read(P_INBUF, P_LEXV);
    lexw = getb(P_LEXV, P_LEXWORDS);
    len = P_LEXV + (lexw * 4);
    len = (getb(len, 1) + getb(len, 0)) - getb(P_LEXV, 5);
    if (!(tbl == 0) && (s16(len) > s16(MAX_CABLEN))) {
      await TOO_LONG();
      continue loop1;
    }
    loop2: for (;;) {
      word = get(P_LEXV, P_LEXSTART + offs);
      if (s16(lexw) > s16(1)) {
        word2 = get(P_LEXV, P_LEXSTART + P_LEXELEN + offs);
      } else {
        break loop2;
      }
      if (!(word == 0) && btst(getb(word, 6), 4)) {
        lexw = lexw - 1;
        offs = offs + P_LEXELEN;
      } else {
        break loop2;
      }
    }
    if (lexw != 0) {
      if ((s16(lexw) > s16(1)) && (word == W.HANG) && (word2 == W.UP) && hasFlag(MACHINE, SEEN)) {
        g.PRSO = MACHINE;
        await V_HANGUP();
        return false;
      } else if (word == W.QUIT || word == W.Q) {
        await V_QUIT();
      } else if (word == W.RESTART) {
        await V_RESTART();
      } else if (word == W.RESTORE) {
        await V_RESTORE();
      } else if (word == W.SAVE) {
        await V_SAVE();
      } else {
        break loop1;
      }
    }
    tell("\"Eh? Didn't get that.\"\n");
  }
  if (!(tbl == 0)) {
    dptr = 1;
    sptr = getb(P_LEXV, 5);
    loop3: for (;;) {
      x = getb(P_INBUF, sptr);
      putb(tbl, dptr, x);
      sptr = sptr + 1;
      if (s16(dptr = dptr + 1) > s16(len)) {
        putb(tbl, 0, len);
        break loop3;
      }
    }
  }
  if (otbl) {
    len = get(otbl, 0);
    dptr = 1;
    sptr = lexw;
    for (;;) {
      if ((s16(sptr = sptr - 1) < s16(0)) || (s16(dptr) > s16(3))) {
        return lexw;
      }
      word = get(P_LEXV, P_LEXSTART + (offs = offs + 1));
      if (!(word == W.SAY || word == W.QUOTE)) {
        put(otbl, dptr, word);
        dptr = dptr + 1;
      }
      offs = offs + 1;
    }
  } else {
    if (!alpha && !tbl && !word) {
      word = await STR2NUM(offs * 2);
    }
    if (!alpha && !word) {
      return word2;
    } else {
      return word;
    }
  }
}

async function STR2NUM(wnum) {
  let len = 0, dptr = 0, sptr = 0, word = 0, x = 0;
  len = getb(P_LEXV, wnum + 4);
  sptr = getb(P_LEXV, wnum + 5);
  dptr = 1;
  word = 0;
  loop1: for (;;) {
    x = getb(P_INBUF, sptr);
    if ((s16(x) > s16(NaN)) && (s16(x) < s16(NaN))) {
      word = (word * 10) + x + NaN;
      sptr = sptr + 1;
      if (s16(dptr = dptr + 1) > s16(len)) {
        break loop1;
      }
    } else {
      word = false;
      break loop1;
    }
  }
  return word;
}

