async function CAB_F() {
  let cs = getb(34108, 11), turns = getb(34108, 10);
  if (((cs == CAB_HERE || cs == CAB_NEEDS_ID) || (g.HERE == CAB_ROOM)) && ((await EXITING$()) || isVerb(V.ENTER, V.OPEN, V.WALK_TO, V.KNOCK, V.LOOK_INSIDE))) {
    if (g.HERE == CAB_ROOM) {
      if ((await EXITING$()) || isVerb(V.OPEN)) {
        await DO_WALK(P.OUT);
      } else if (isVerb(V.LOOK_INSIDE)) {
        await PERFORM(V.LOOK);
      } else {
        tell(S(YOURE_ALREADY_STR), "in it", S(PERIOD));
      }
      return true;
    } else if (g.HERE == OUTSIDE_HOUSE) {
      if (isVerb(V.LOOK_INSIDE)) {
        tell("It's just an ordinary cab.\n");
        return true;
      } else if (!(hasFlag(CAB_DRIVER, SEEN))) {
        await PERFORM(V.TELL, CAB_DRIVER);
        return true;
      } else {
        tell("\"You're gonna have to show some ID first.\"\n");
        return true;
      }
    } else {
      tell("The Passengers' Teleportation Device hasn't been approved for use yet, so you'll have to go to where the cab is first.\n");
      return true;
    }
  } else if (isVerb(V.WAIT_FOR, V.WAVE_AT)) {
    if (g.HERE == CAB_ROOM) {
      tell(S(YOURE_ALREADY_STR), "in it", S(PERIOD));
      return true;
    } else if (cs == CAB_HERE) {
      return (await ITS_ALREADY("here"));
    } else if (cs == CAB_SENT) {
      if (isVerb(V.WAVE_AT)) {
        if (s16(turns) <= s16(1)) {
          await CTHE_PRINT(CAB);
          tell(" pays no attention to you.\n");
          return true;
        } else {
          tell("There's no cab here.\n");
          return true;
        }
      } else {
        return await V_WAIT(getb(34108, 10) + 1);
      }
    } else if ((cs == CAB_INIT) || getb(34108, 14)) {
      await V_WAIT(10);
      if (!g.CLOCK_WAIT$) {
        if (isVerb(V.WAVE_AT)) {
          tell("There's no cab here.\n");
          return true;
        } else {
          tell("Perhaps you should call the cab again.\n");
          return true;
        }
      } else {
        return false;
      }
    } else {
      return false;
    }
  } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE) && (((cs == CAB_SENT) && (s16(turns) <= s16(1))) || (cs == CAB_HERE || cs == CAB_NEEDS_ID))) {
    tell("It's just an ordinary cab.\n");
    return true;
  } else if (await CAB_AND_DRIVER_AVAILABLE()) {
    return false;
  } else if ((s16(turns) <= s16(1)) && (g.HERE == OUTSIDE_HOUSE) && (cs == CAB_SENT) && isVerb(V.ENTER, V.OPEN, V.WALK_TO, V.KNOCK, V.LOOK_INSIDE)) {
    tell("The Passengers' Teleportation Device hasn't been approved for use yet, so you'll have to go to where the cab is first.\n");
    return true;
  } else {
    tell(S(YOU_SEE), "no cab here.\n");
    return true;
  }
}

