async function DRAW_FORM(which, name) {
  let rline = 0, len = 0, fields = 0, tf = 0;
  g.MARGIN = div(g.WIDTH - FORM_WIDTH, 2);
  g.MARGIN = g.MARGIN + 1;
  g.FLINE = div(g.HEIGHT - FORM_LENGTH, 2);
  g.FLINE = g.FLINE + 1;
  clearScreen(-1);
  splitWindow(g.HEIGHT - 1);
  setWindow(S_WINDOW);
  bufOut(false);
  highlight(H_NORMAL);
  highlight(H_INVERSE);
  await BLANK_LINE(0);
  await SET_FORM_CURS(1, 0);
  tell(S(name));
  await BLANK_LINE(2);
  await OPEN_LINE(3);
  tell("Type ^ to back up a field. Thank you.");
  await CLOSE_LINE(3);
  await BLANK_LINE(4);
  rline = FIRST_FORM_LINE;
  len = get(which, 0);
  fields = (which + 2);
  tf = 0;
  loop1: for (;;) {
    if (len == 0) {
      await BLANK_LINE(rline + 1);
      break loop1;
    }
    tf = get(fields, 0);
    await OPEN_LINE(rline = getb(tf, 8));
    tell(S(get(tf, 0)));
    if ((s16(len) > s16(1)) && (tf = get(fields, 1)) && eq(getb(tf, 8), rline)) {
      await SET_FORM_CURS(rline, getb(tf, 7));
      fields = fields + 2;
      len = len - 1;
      tell(S(get(tf, 0)));
    }
    await CLOSE_LINE(rline);
    fields = fields + 2;
    len = len - 1;
  }
  return highlight(H_NORMAL);
}

async function SET_FORM_CURS(y, x) {
  g.FORM_X = x;
  g.FORM_Y = y;
  return cursorSet(g.FLINE + y, x + g.MARGIN);
}

async function BLANK_LINE(n_) {
  await SET_FORM_CURS(n_, 0);
  return await PRINT_SPACES(FORM_WIDTH);
}

async function OPEN_LINE(n_) {
  await SET_FORM_CURS(n_, 0);
  tell(" ");
  highlight(H_NORMAL);
  return highlight(H_BOLD);
}

async function CLOSE_LINE(n_) {
  await SET_FORM_CURS(n_, FORM_WIDTH - 1);
  highlight(H_NORMAL);
  highlight(H_INVERSE);
  tell(" ");
  return true;
}

async function FERROR(str, note$ = false) {
  await CLEAR_FERROR();
  g.FERROR_COUNT = g.FERROR_COUNT + 1;
  if (g.FORM_COMPUTER$) {
    await SET_FORM_CURS(COMPUTER_ERROR_LINE, 1);
    highlight(H_NORMAL);
  } else {
    await SET_FORM_CURS(ERROR_LINE, 1);
    highlight(H_BOLD);
  }
  if (!(note$ == 0)) {
    tell("NOTE");
  } else {
    tell("ERROR");
  }
  tell(": ", S(str), ".");
  highlight(H_NORMAL);
  if (g.FORM_COMPUTER$) {
    highlight(H_INVERSE);
  }
  await SET_FORM_CURS(g.FY, g.FX);
  return sound(S_BOOP);
}

async function CLEAR_FERROR() {
  setWindow(S_WINDOW);
  highlight(H_NORMAL);
  if (g.FORM_COMPUTER$) {
    await SET_FORM_CURS(COMPUTER_ERROR_LINE, 1);
    await PRINT_SPACES(COMPUTER_WIDTH);
    highlight(H_INVERSE);
  } else {
    await SET_FORM_CURS(ERROR_LINE, 1);
    await PRINT_SPACES(FORM_WIDTH - 2);
  }
  return await SET_FORM_CURS(g.FY, g.FX);
}

async function FILL_FIELD(field, which, err$ = false) {
  let cnt = 0, ptr = FIELD_DATA_OFFSET, max = 0, char = 0, tbl = 0, oldlen = 0, echo$ = true;
  if (g.FORM_COMPUTER$) {
    highlight(H_INVERSE);
  } else {
    highlight(H_NORMAL);
  }
  tbl = get(which, field);
  if (!(get(tbl, 1) == 0) && !(await apply(get(tbl, 1), FORM_DO_ECHO$, tbl))) {
    echo$ = false;
  }
  max = getb(tbl, 9);
  g.FX = getb(tbl, 7) + getb(tbl, 6);
  g.FY = getb(tbl, 8);
  oldlen = getb(tbl, 11);
  await SET_FORM_CURS(g.FY, g.FX);
  if ((cnt == 0) && (s16(oldlen) > s16(0))) {
    putb(tbl, 11, 0);
    oldlen = 0;
    await PRINT_SPACES(max);
    await SET_FORM_CURS(g.FY, g.FX);
  }
  loop1: for (;;) {
    char = await readChar(1);
    if (char == 13) {
      if (cnt == 0) {
        if (s16(oldlen) > s16(0)) {
          return true;
        }
        err$ = true;
        if (!(getb(34152, 3) == 0)) {
          (await FERROR("INCOMPLETE-FIELD-ENTRY"));
        } else {
          (await FERROR("Incomplete field entry"));
        }
        continue loop1;
      } else {
        if (err$) {
          err$ = false;
          await CLEAR_FERROR();
        }
        putb(tbl, 11, cnt);
        await FORM_NAME(field);
        return true;
      }
    } else if (char == 94 || char == 14) {
      if (err$) {
        await CLEAR_FERROR();
      }
      if (s16(oldlen) > s16(0)) {
        putb(tbl, 11, oldlen);
      }
      return false;
    } else if (char == 127 || char == 8) {
      if (cnt == 0) {
        err$ = true;
        if (!(getb(34152, 3) == 0)) {
          (await FERROR("1ST-CHAR-IN-FIELD"));
        } else {
          (await FERROR("1st char in field"));
        }
        continue loop1;
      }
      if (err$) {
        err$ = false;
        await CLEAR_FERROR();
      }
      putb(tbl, 11, cnt = cnt - 1);
      if (echo$) {
        g.FX = g.FX - 1;
        await SET_FORM_CURS(g.FY, g.FX);
        printC(32);
        await SET_FORM_CURS(g.FY, g.FX);
      }
      putb(tbl, ptr = ptr - 1, 0);
      continue loop1;
    } else if (cnt == max) {
      err$ = true;
      (await FERROR("End of field"));
      continue loop1;
    } else if (!(get(tbl, 1)) || (await apply(get(tbl, 1), FORM_ADD_CHAR, tbl, char))) {
      if ((s16(char) > s16(NaN)) && (s16(char) < s16(NaN))) {
        char = char - 32;
      }
      if (echo$) {
        printC(char);
        g.FX = g.FX + 1;
      }
      putb(tbl, ptr, char);
      ptr = ptr + 1;
      putb(tbl, 11, cnt = cnt + 1);
    } else {
      err$ = true;
      continue loop1;
    }
    if (err$) {
      err$ = false;
      await CLEAR_FERROR();
    }
  }
}

