async function PICK_FIELD(which, len, histvec, histlen) {
  let n_ = 0, f = 0, passes = 0, m = 0;
  passes = 0;
  m = 0;
  loop1: for (;;) {
    if (s16(passes = passes + 1) > s16(len)) {
      if (s16(m = m + 1) > s16(len)) {
        n_ = -1;
        break loop1;
      }
      n_ = m - 1;
    } else {
      n_ = random(len);
      n_ = n_ - 1;
    }
    if (getb(f = get(which, n_), 10) == 0) {
      if (!(get(f, 1)) || !((await apply(get(f, 1), FORM_OK_TO_ENTER_FIELD$, f)) == 0)) {
        putb(get(which, n_), 10, 1);
        putb(histvec, histlen, n_);
        break loop1;
      }
    }
  }
  return n_;
}

async function FILL_FORM(which, name) {
  let x = 0, tbl = 0, y = 0, fieldct = get(which, 0), hist = FORM_HISTORY, histlen = 0, n_ = 0, bogus_errors = 0, zz = 0, f = 0, err$ = 0, errval = 0;
  g.FORM_COMPUTER$ = false;
  g.FERROR_COUNT = 0;
  await DRAW_FORM(which, name);
  which = which + 2;
  zz = 0;
  f = 0;
  loop1: for (;;) {
    if (!(getb(f = get(which, zz), 10) == 0) && !(get(f, 1) == 0)) {
      await apply(get(f, 1), FORM_FIELD_RESET, f);
    }
    putb(get(which, zz), 10, 0);
    if (s16(zz = zz + 1) >= s16(fieldct)) {
      break loop1;
    }
  }
  n_ = await PICK_FIELD(which, fieldct, hist, 0);
  bogus_errors = 0;
  err$ = false;
  errval = 0;
  loop2: for (;;) {
    x = await FILL_FIELD(n_, which, err$);
    err$ = false;
    tbl = get(which, n_);
    if (!x) {
      if (histlen == 0) {
        (await FERROR("Top of form"));
        err$ = true;
        continue loop2;
      }
      x = getb(tbl, 7) + getb(tbl, 6);
      y = getb(tbl, 8);
      await SET_FORM_CURS(y, x);
      highlight(H_NORMAL);
      await PRINT_SPACES(getb(tbl, 9));
      putb(tbl, 11, 0);
      putb(tbl, 10, 0);
      n_ = getb(hist, histlen = histlen - 1);
      continue loop2;
    } else if (!(get(tbl, 1) == 0)) {
      errval = await apply(get(tbl, 1), FORM_EXIT_FIELD, tbl);
      if (!errval) {
        err$ = true;
        continue loop2;
      }
      if (errval == FATAL_VALUE || errval == 3) {
        err$ = true;
        if ((errval == FATAL_VALUE) && (s16(bogus_errors = bogus_errors + 1) <= s16(3))) {
          continue loop2;
        }
      }
    }
    if (prob(35) && !err$ && !(get(tbl, 2) == 0)) {
      await FERROR(await PICK_ONE(get(tbl, 2)), true);
      err$ = true;
    }
    if (eq(histlen = histlen + 1, fieldct)) {
      break loop2;
    }
    bogus_errors = 0;
    n_ = await PICK_FIELD(which, fieldct, hist, histlen);
    if (n_ == (-1)) {
      break loop2;
    }
  }
  clearScreen(S_WINDOW);
  clearScreen(S_TEXT);
  await INIT_STATUS_LINE();
  crlf();
  if (s16(g.FERROR_COUNT) > s16(0)) {
    await UPDATE_BP(g.FERROR_COUNT);
    crlf();
  }
  dirOut(D_SCREEN_OFF);
  await SHOW_FIELDS(which - 2);
  dirOut(D_SCREEN_ON);
  return true;
}

async function TEXT_TO_VALUE(tbl, dot_ok = false) {
  let sum = 0, len = 0, x = 0, dot_seen = false, ptr = 0;
  len = getb(tbl, 0);
  ptr = 1;
  loop1: for (;;) {
    x = getb(tbl, ptr);
    if ((s16(x) > s16(NaN)) && (s16(x) < s16(NaN))) {
      if (s16(sum) > s16(MAX_NUM_DIV_10)) {
        return -1;
      }
      sum = sum * 10;
      x = x - 48;
      if (s16(sum) > s16(MAX_NUM - x)) {
        return -1;
      }
      sum = sum + x;
    } else if (dot_ok && (x == 46)) {
      dot_ok = false;
      dot_seen = true;
    } else {
      return -2;
    }
    if (s16(ptr = ptr + 1) > s16(len)) {
      if (dot_ok && !dot_seen) {
        if (s16(sum) > s16(MAX_NUM_DIV_100)) {
          return -1;
        }
        sum = sum * 100;
      }
      break loop1;
    }
  }
  return sum;
}

