async function MATCH_AIRLINE_NAME(adj, nam, tbl) {
  let tt = 0, obj = AIRLINE, len = get(tbl, 0), n_ = 0;
  if (!adj && !nam) {
    return false;
  }
  if ((nam == W.INTNUM) && (g.P_NUMBER == 42)) {
    return THE_FLIGHT;
  }
  if ((tt = getPropAddr(obj, P.SYNONYM)) && inTable(nam, tt, div(propSize(tt), 2))) {
    nam = false;
  }
  if (adj && (tt = getPropAddr(obj, P.ADJECTIVE)) && inTable(nam, tt, div(propSize(tt), 2))) {
    adj = false;
  }
  if (!(nam || adj)) {
    tell("You'll have to be more specific. Do you mean ");
    tbl = AIRLINE_NAMES;
    n_ = 0;
    loop1: for (;;) {
      tell(S(get(tbl, n_)));
      if (s16(n_ = n_ + 1) > s16(30)) {
        tell(", or ", S(get(tbl, n_)), "?\n");
        break loop1;
      }
      tell(", ");
    }
    putProp(obj, P.PSEUDO_TABLE, -1);
    return obj;
  } else {
    tbl = tbl + 2;
    loop2: for (;;) {
      if (!nam || (nam == get(tbl, 1))) {
        if (!adj || (adj == get(tbl, 0)) || (adj == get(tbl, 1))) {
          if (s16(adj = get(tbl, 2)) < s16(0)) {
            adj = 0 - adj;
          }
          putProp(obj, P.PSEUDO_TABLE, adj);
          break loop2;
        }
      }
      if (s16(len = len - 3) <= s16(2)) {
        putProp(obj, P.PSEUDO_TABLE, -1);
        obj = false;
        break loop2;
      }
      tbl = tbl + 6;
    }
    return obj;
  }
}

async function AIRLINE_F() {
  let id = 0, bits = 0, mask = 1, arn = 0;
  id = getProp(g.PRSO, P.PSEUDO_TABLE);
  if (!(hasFlag(g.HERE, IN_TERMINAL))) {
    tell("Airlines are usually found only at airports.\n");
    return true;
  } else if (!(g.NOW_PRSI$ == 0)) {
    return false;
  } else if (isVerb(V.EXAMINE)) {
    if (id != (-1)) {
      await CANT_SEE_MUCH();
    }
    return true;
  } else if (await ENTERING$()) {
    id = getProp(g.PRSO, P.PSEUDO_TABLE);
    if (id == (-1)) {
      await ORPHAN_VERB(false, ACT.ENTER);
    } else if (g.HERE == AIRPORT_ENTRANCE) {
      arn = getb(34172, 0);
      arn = arn - 1;
      if (s16(id) > s16(15)) {
        bits = get(AIRLINE_BITS, arn * 2);
        id = id - 16;
      } else {
        bits = get(AIRLINE_BITS, (arn * 2) + 1);
      }
      mask = await DO_LSH(id = id + 1);
      if (btst(bits, mask)) {
        await AIRLINE_WALK(P.NORTH);
      } else {
        await V_WALK_AROUND();
      }
    } else if (g.HERE == AIRLINE_DESK) {
      if (id == getb(34172, 5)) {
        await ALREADY_THERE();
      } else {
        await AIRLINE_WALK(P.SOUTH);
      }
    } else if (g.HERE == AIRPORT_CONCOURSE) {
      if (mask = inTable(id, CURRENT_SIGNS, 10)) {
        if (eq(get(mask, 1), "east")) {
          await AIRLINE_WALK(P.EAST);
        } else {
          await AIRLINE_WALK(P.WEST);
        }
      } else {
        await V_WALK_AROUND();
      }
    } else {
      await ORPHAN_VERB(false, ACT.ENTER);
    }
    return true;
  } else {
    return false;
  }
}

