async function DUCT_F(context = false) {
  let dn = getb(34172, 17);
  if (context == M_ENTERING) {
    if (dn == 0) {
      putb(34172, 17, 1);
    }
    if (await BOTTOM_DUCT$()) {
      clearFlag(GRATE, INVISIBLE);
    } else {
      setFlag(GRATE, INVISIBLE);
    }
    return false;
  } else if (context == M_LOOK) {
    if (dn == 1) {
      tell("You're at the bottom of an air conditioning duct that curves upward to the south. A");
      await OPEN_CLOSED(GRATE);
      tell(" leads downward.\n");
      return true;
    } else if (dn == 2) {
      tell("You're in a narrow air conditioning duct that curves upward to the east, and downward to the north.\n");
      return true;
    } else if (dn == 3) {
      tell("You're in a narrow air conditioning duct that curves upward to the north, and downward to the west.\n");
      return true;
    } else {
      return false;
    }
  } else if (!(context == 0)) {
    return false;
  } else if (!(g.NOW_PRSI$ == 0)) {
    return false;
  } else if (isVerb(V.CLIMB_UP, V.CLIMB_ON, V.CLIMB_OVER)) {
    await DO_WALK(P.UP);
    return true;
  } else if (await ENTERING$()) {
    if (g.HERE == PILLAR_B) {
      await DO_WALK(P.UP);
    } else if (g.HERE == IN_TOWER) {
      await DO_WALK(P.IN);
    } else {
      await ALREADY_IN();
    }
    return true;
  } else if (await EXITING$()) {
    if (g.HERE == PILLAR_B) {
      await NOT_IN();
    } else {
      await DO_WALK(P.DOWN);
    }
    return true;
  } else if (isVerb(V.CLIMB_DOWN)) {
    if (g.HERE == PILLAR_B) {
      await NOT_IN();
    } else {
      await DO_WALK(P.DOWN);
    }
    return true;
  } else if (await HERE_F()) {
    return true;
  } else {
    return false;
  }
}

