async function I_CONSOLE(cr = true) {
  let plane$ = true, n_ = 0;
  if (!(getb(34172, 19) == 0) || !(getb(34172, 18) == 0)) {
    plane$ = false;
  }
  n_ = getb(34172, 20);
  putb(34172, 20, n_ = n_ - 1);
  if (n_ == 3) {
    if (!plane$) {
      return false;
    } else if (!(cr == 0)) {
      crlf();
    }
    tell("A console radio crackles to life nearby. \"Air Zalagasa flight 42 to ");
    await SHOW_FIELD(CITY_NAME);
    tell(" tower. Request permission to take off.\"\n");
    return true;
  } else if (n_ == 2) {
    if (!(cr == 0)) {
      crlf();
    }
    tell("The controllers continue to grovel at your smoky apparition.\n");
    if (!plane$) {
      return true;
    }
    tell("\n\"Air Zalagasa flight 42 to Paris, calling ");
    await SHOW_FIELD(CITY_NAME);
    tell(" tower.\" The radio voice sounds a bit miffed. \"Are you guys asleep up there? Permission to take off, granted or denied?\"\n");
    return true;
  } else if (n_ == 1) {
    if (!(cr == 0)) {
      crlf();
    }
    tell("The air traffic controllers are starting to frown. In the absence of any more smoke and lights you are beginning to appear somewhat less than immortal; distinctly shabby, in fact.\n\nThere is a very very nasty pause.\n");
    if (!plane$) {
      return true;
    }
    tell("\nThe radio crackles with indignation. \"");
    await SHOW_FIELD(CITY_NAME);
    tell(" tower! ");
    await SHOW_FIELD(CITY_NAME);
    tell(" tower! Air Zalagasa flight 42, requesting immediate permission to take off! Permission granted or denied?\"\n");
    return true;
  }
  if (!(cr == 0)) {
    crlf();
  }
  if (!(plane$ == 0)) {
    tell("The Air Zalagasa pilot on the radio utters an oath that will probably cost him his licence. ");
    await PLANE_TAKES_OFF();
    crlf();
  }
  tell("By now, the controllers have rather decided that you're not any sort of god");
  if (!(g.SEX == 0)) {
    tell("dess");
  }
  tell(" or deity, but are probably instead a stupid air conditioning repairperson fumbling around in the ducts with no business disrupting the vital work of air traffic controllers.");
  await POLICE();
  return true;
}

async function PLANE_TAKES_OFF() {
  putb(34172, 19, true);
  await DEQUEUE(I_CONSOLE.id);
  tell("Moments later, a huge intercontinental jet roars past the tower, barely missing a Piper Cub as it climbs out of sight.\n");
  return true;
}

