async function CONTROLLERS_F(context = false) {
  let flight = false, request = false;
  if (context == M_OBJDESC) {
    await CPRINTA(CONTROLLERS);
    tell(" are staring at you");
    if (!(hasFlag(CONTROLLERS, SEEN))) {
      tell(" in awe");
    }
    tell(".");
    return true;
  }
  if ((g.PRSO == THE_FLIGHT) || ((g.PRSO == INTNUM) && (g.P_NUMBER == 42) && eq(get(P_ADJW, 0), false, W.FLIGHT, W.OMNIA, W.GALLIA))) {
    flight = true;
  } else if ((g.PRSO == REQUEST_OBJECT) && ((await NOUN_USED$(W.REQUEST)) || (await NOUN_USED$(W.PERMISSION)))) {
    request = true;
  }
  if (context == M_WINNER) {
    if (isVerb(V.HELLO) && (g.P_PRSA_WORD == W.NO) && (g.PRSO == ROOMS)) {
      await THEY_STOP_FLIGHT();
      return FATAL_VALUE;
    } else if (isVerb(V.DENY, V.REFUSE, V.LAMP_OFF) && (!(request == 0) || !(flight == 0))) {
      await THEY_STOP_FLIGHT();
      return FATAL_VALUE;
    } else if (!(flight == 0) && ((isVerb(V.SPIN) && (g.P_PRSA_WORD == W.TURN || g.P_PRSA_WORD == W.RECALL)) || (isVerb(V.LAMP_OFF) && (g.P_PRSA_WORD == W.STOP || g.P_PRSA_WORD == W.HALT)))) {
      await THEY_STOP_FLIGHT();
      return FATAL_VALUE;
    } else if (isVerb(V.GET_FOR) && !(flight == 0) && (g.PRSI == ME || g.PRSI == AIRPORT)) {
      await THEY_STOP_FLIGHT();
      return FATAL_VALUE;
    } else if (isVerb(V.GRANT) && request) {
      await THEY_RELEASE_FLIGHT();
      return FATAL_VALUE;
    } else if (g.PRSO == ME) {
      if (isVerb(V.TELL_ABOUT)) {
        await ASK_CONTROLLERS_ABOUT();
        return FATAL_VALUE;
      } else if (isVerb(V.SSHOW, V.SGIVE, V.SSELL)) {
        await ASK_CONTROLLERS_FOR();
        return FATAL_VALUE;
      }
    } else if (g.PRSI == ME) {
      if (isVerb(V.SHOW, V.GIVE, V.SELL)) {
        await ASK_CONTROLLERS_FOR(g.PRSO);
        return FATAL_VALUE;
      }
    }
    await CTHE_PRINT(g.WINNER);
    tell(" are too awed to respond.\n");
    return FATAL_VALUE;
  } else if (!(context == 0)) {
    return false;
  } else if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.SHOW)) {
      await CTHEI_PRINT();
      tell(" are struck dumb by the sight of your ");
      await DPRINT(g.PRSO);
      tell(S(PERIOD));
      return true;
    } else if (isVerb(V.GIVE, V.SELL)) {
      await CTHEI_PRINT();
      tell(" are too awed by the magnificence of your offer to accept it.\n");
      return true;
    }
    return false;
  } else if (isVerb(V.TELL)) {
    return false;
  } else if (isVerb(V.EXAMINE)) {
    await CTHE_PRINT();
    tell(" stare back at you in awe and wonder.\n");
    return true;
  } else if (isVerb(V.ASK_ABOUT)) {
    await ASK_CONTROLLERS_ABOUT();
    return true;
  } else if (isVerb(V.ASK_FOR)) {
    await ASK_CONTROLLERS_FOR();
    return true;
  } else {
    return false;
  }
}

