async function PARANOID_IS_ANGRY() {
  let wrd = 0, t1 = 0, t2 = 0, t1l = 0, t2l = 0, al = 0, j = 0, k = 0, theq = 0, qtb = P_Q, atb = P_A, i = 0, pscore = 0;
  tell("\nThe paranoid householder stares first at you, then at the weirdo, with growing confusion and disbelief. He starts to say something, then stops. He then stops starting to say it and starts. \"How come...\", he says. Then he stops again. He clearly believes that this whole thing is part of his paranoia, and then, equally clearly, decides that it doesn't matter.\n\n\"Right. One of you is an impostor. I'm pretty sure that it's you, ");
  await PRINT_LAST_NAME();
  tell(", but, to be sure, I'm going to grill... going to ask you a few simple questions. Right.\"\n\n");
  i = 0;
  pscore = 0;
  for (;;) {
    if (i == NUM_QA) {
      if (s16(pscore) < s16(MIN_SCORE)) {
        await CTHE_PRINT(THE_PARANOID);
        tell(" says, \"You are obviously an impostor.");
        await SPY_JIGS_UP();
      } else {
        await CTHE_PRINT(THE_PARANOID);
        tell(" says, \"You passed the test. This means that either one of you could be the impostor.\" He presses a button on the wall, and a trap door opens in the floor. Both you and the stranger fall into a gaol below", S(PCR));
        move(SPY, JAIL);
        await GOTO(JAIL);
      }
      return true;
    }
    i = i + 1;
    k = random(NUM_Q);
    k = k - 1;
    loop2: for (;;) {
      theq = get(qtb, k);
      if (!(theq == 0)) {
        break loop2;
      }
      if (k == (NUM_Q - 1)) {
        k = 0;
      } else {
        k = k + 1;
      }
    }
    tell("\"", S(theq), "\"\n");
    al = await GET_CABWORD(false, false, ANS_TABLE);
    t1 = get(atb, k);
    t1l = get(t1, 0);
    loop3: for (;;) {
      if (s16(t1l = t1l - 1) < s16(0)) {
        break loop3;
      }
      t1 = t1 + 2;
      t2 = get(t1, 0);
      t2l = get(t2, 0);
      if (al == t2l) {
        j = 1;
        loop4: for (;;) {
          if (s16(t2l = t2l - 1) < s16(0)) {
            pscore = pscore + 1;
            t1l = 0;
            put(qtb, k, 0);
            break loop4;
          }
          if (await W_COMP(get(t2, j), get(ANS_TABLE, j))) {
            j = j + 1;
          } else if ((t1l == 0) && (get(qtb, k) != 0)) {
            put(qtb, k, 0);
            tell("\"Are you sure?\"\n");
            if ((await SAID_YES$("\"Just answer yes or no!\""))) {
              break loop4;
            } else {
              tell("\"", S(theq), "\"\n");
              al = await GET_CABWORD(false, false, ANS_TABLE);
              t1 = get(atb, k);
              t1l = get(t1, 0);
              break loop4;
            }
          } else {
            break loop4;
          }
        }
      } else if ((t1l == 0) && (get(qtb, k) != 0)) {
        put(qtb, k, 0);
        tell("Are you sure?\n");
        if ((await SAID_YES$("Just answer yes or no!"))) {
        } else {
          tell(S(theq), "\n");
          al = await GET_CABWORD(false, false, ANS_TABLE);
          t1 = get(atb, k);
          t1l = get(t1, 0);
        }
      }
    }
  }
}

async function W_COMP(tb1, indx) {
  let lni = div(indx, 256), strt = (indx & 255), aln = getb(tb1, 0), i = 1, val = true, c1 = 0, c2 = 0;
  if ((lni == aln) || (lni == (aln - 1))) {
    loop1: for (;;) {
      if ((s16(c1 = getb(tb1, i)) >= s16(65)) && (s16(c1) <= s16(90))) {
        c1 = c1 + NaN;
      }
      if ((s16(c2 = getb(P_INBUF, strt)) >= s16(65)) && (s16(c2) <= s16(90))) {
        c2 = c2 + NaN;
      }
      if (c1 != c2) {
        val = false;
        break loop1;
      }
      if (s16(i = i + 1) > s16(lni)) {
        if ((lni != aln) && (getb(tb1, i) != 83)) {
          val = false;
        }
        break loop1;
      }
      strt = strt + 1;
    }
    return val;
  } else {
    return false;
  }
}

