async function PICK_MESSAGE(rst) {
  if (!(g.CURRENT_MESSAGE == 0)) {
  } else if (await COMP_WORDS_FROM_INBUF(UNFO_TBL, rst)) {
    g.CURRENT_MESSAGE = UNFO_MESSAGE;
  } else if (!g.COMP_WORD_FATAL$) {
    if (await COMP_WORDS_FROM_INBUF(INCI_TBL, rst)) {
      g.CURRENT_MESSAGE = INCI_MESSAGE;
    }
  }
  return g.CURRENT_MESSAGE;
}

async function COMP_WORDS_FROM_INBUF(tbl, rst) {
  let buf = 0, cnt = 0, tlen = 0, ocnt = 0, which = 0, wrd = 0;
  if (tbl == UNFO_TBL) {
    which = UNFO_MESSAGE;
  } else {
    which = INCI_MESSAGE;
  }
  if (!g.P_CONT) {
    return false;
  }
  buf = P_LEXV + (2 * g.P_CONT);
  cnt = getb(P_LEXV, P_LEXWORDS);
  ocnt = cnt;
  tlen = get(tbl, 0) - rst;
  tbl = tbl + ((1 + rst) * 2);
  g.COMP_WORD_FATAL$ = false;
  if (s16(cnt) >= s16(tlen)) {
    wrd = 0;
    loop1: for (;;) {
      if (cnt == 0) {
        if (s16(tlen) <= s16(0)) {
          g.CURRENT_MESSAGE = which;
          return true;
        }
        return false;
      }
      if (!(wrd = get(buf, 0))) {
        await UNKNOWN_WORD(g.P_CONT + (P_LEXELEN * (ocnt - cnt)));
        g.COMP_WORD_FATAL$ = true;
        return false;
      }
      if (wrd == W.QUOTE) {
        cnt = cnt - 1;
        buf = buf + (2 * P_LEXELEN);
        continue loop1;
      } else if (wrd != get(tbl, 0)) {
        if ((s16(cnt) <= s16(2)) && (wrd == W.PERIOD)) {
        } else if ((wrd != W.THEN) || (get(tbl, 0) != W.COMMA)) {
          return false;
        }
      }
      cnt = cnt - 1;
      tlen = tlen - 1;
      buf = buf + (2 * P_LEXELEN);
      tbl = tbl + 2;
    }
  } else {
    return false;
  }
}

