async function SWITCH_STATE(handle) {
  let n_ = getProp(handle, P.HANDLE_NUMBER), val = 0;
  if (!(getb(HANDLE_STATE, n_))) {
    val = 1;
  }
  putb(HANDLE_STATE, n_, val);
  await CTHE_PRINT(handle);
  tell(" is now pointing ");
  if (!val) {
    tell("up");
  } else {
    tell("down");
  }
  tell(S(PERIOD));
  return true;
}

async function CHECK_MOVE(h1, h2) {
  let hs = HANDLE_STATE, tmp = 0;
  if (s16(g.HANDLE_TURNS) < s16(0)) {
    if (!(getb(hs, 0)) && !(getb(hs, 1) == 0) && !(getb(hs, 0))) {
      g.HANDLE_TURNS = 0;
      return true;
    } else {
      return false;
    }
  } else {
    if (s16(getProp(h2, P.HANDLE_NUMBER)) < s16(getProp(h1, P.HANDLE_NUMBER))) {
      tmp = h1;
      h1 = h2;
      h2 = tmp;
    }
    g.HANDLE_TURNS = g.HANDLE_TURNS + 1;
    if (g.HANDLE_TURNS == 1) {
      if ((h1 == LEFT_HANDLE) && (h2 == MIDDLE_HANDLE)) {
        return true;
      } else if ((h1 == MIDDLE_HANDLE) && (h2 == RIGHT_HANDLE)) {
        return true;
      } else {
        return false;
      }
    } else if (g.HANDLE_TURNS == 2) {
      if ((h1 == LEFT_HANDLE) && (h2 == RIGHT_HANDLE)) {
        return true;
      } else {
        return false;
      }
    } else if (g.HANDLE_TURNS == 3) {
      if (!(getb(hs, 0) == 0) && !(getb(hs, 1) == 0) && !(getb(hs, 2) == 0)) {
        return true;
      } else {
        return false;
      }
    } else {
      return false;
    }
  }
}

