async function TO_BANK() {
  let ba = get(34129, 0), h = 0, t1 = 0, t2 = 0, t3 = 0, t4 = 0, closed = false;
  if (!(g.END_GAME$ == 0)) {
    (await FROB_IS_CLOSED("bank"));
    return false;
  }
  putb(34124, 11, STATE_INIT);
  putb(34124, 0, 0);
  if (ba == 0) {
    if (prob(50)) {
      ba = random(10);
      put(34129, 0, 0 - ba);
      closed = true;
    } else {
      ba = random(10) + 20;
      put(34129, 0, ba);
    }
    t1 = random(NUMBER_TELLERS);
    put(34125, 0, t1);
    t2 = random(NUMBER_TELLERS);
    if (t2 == t1) {
      if (t2 == NUMBER_TELLERS) {
        t2 = 1;
      } else {
        t2 = t2 + 1;
      }
    }
    t3 = random(NUMBER_TELLERS);
    loop1: for (;;) {
      if (t3 == t1 || t3 == t2) {
        if (t3 == NUMBER_TELLERS) {
          t3 = 1;
        } else {
          t3 = t3 + 1;
        }
      } else {
        break loop1;
      }
    }
    t4 = random(NUMBER_TELLERS);
    loop2: for (;;) {
      if (t4 == t3 || t4 == t1 || t4 == t2) {
        if (t4 == NUMBER_TELLERS) {
          t4 = 1;
        } else {
          t4 = t4 + 1;
        }
      } else {
        break loop2;
      }
    }
    put(34127, 0, t2);
    put(34131, 0, t3);
    put(34133, 0, t4);
    await QUEUE(I_BANK_HOURS.id);
  } else if (s16(ba) < s16(0)) {
    ba = 0 - ba;
    closed = true;
  }
  if (!(closed == 0)) {
    tell("You discover the bank is closed for ");
    await PRINT_BANK_DELTA(ba);
    tell(S(PERIOD));
    await I_BANK_HOURS();
    return false;
  } else {
    tell("As you enter, you hear an announcement say, \"WARNING: The bank will close in ");
    await PRINT_BANK_DELTA(ba);
    tell(".\"\n\n");
    return BANK;
  }
}

async function PRINT_BANK_DELTA(ba) {
  let h = 0;
  h = div(ba, 60);
  ba = mod(ba, 60);
  if (h != 0) {
    tell(N(h), " hour");
    if (h != 1) {
      tell("s");
    }
    if (ba != 0) {
      tell(" and ");
    }
  }
  if (ba != 0) {
    tell(N(ba), " minute");
    if (ba != 1) {
      tell("s");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function I_BANK_HOURS() {
  let ba = get(34129, 0), i = 0, val = false;
  i = await ZABS(ba);
  if (eq(i = i - 1, 0)) {
    if (!(loc(PLAYER) == BANK) && !(loc(PLAYER) == ST_A)) {
      await DEQUEUE(I_BANK_HOURS.id);
      i = 0;
    } else if ((s16(ba) > s16(0)) && (loc(PLAYER) == BANK)) {
      tell("\nUnfortunately, the bank has closed. ");
      await LEAVE_BANK(true);
      val = true;
    } else if (s16(ba) > s16(0)) {
      i = 0 - random(10);
    } else {
      i = random(10) + 20;
    }
  } else if (s16(ba) < s16(0)) {
    i = 0 - i;
  }
  put(34129, 0, i);
  return val;
}

