async function BANKWORD$(ptr) {
  let credit = false, addr = false, problem = false, len = 0, wrd = 0, bongo$ = false, money$ = false, form = false, first_ = 2, bal = false, person = false, hold = false;
  wrd = get(34022, 0);
  wrd = get(getPropAddr(BANKSOUND, P.SYNONYM), 0);
  if (wrd == W.BONGO) {
    bongo$ = true;
  }
  len = g.P_LEN;
  loop1: for (;;) {
    if (s16(len = len - 1) < s16(0)) {
      break loop1;
    }
    wrd = get(P_LEXV, ptr);
    if (wrd == W.HOLD) {
      hold = wrd;
    } else if (wrd == W.FORM || wrd == W.FORMS) {
      form = wrd;
    } else if ((wrd == W.PROBLEM || wrd == W.COMPLAINT || wrd == W.TROUBLE) || (wrd == W.CUSTOMER || wrd == W.SERVICE)) {
      problem = wrd;
    } else if (wrd == W.ADDRESS) {
      addr = wrd;
    } else if (wrd == W.MONEY || wrd == W.CASH) {
      money$ = wrd;
    } else if ((wrd == W.CREDIT || wrd == W.CARD || wrd == W.BEEZER) || (wrd == W.EXCESS)) {
      credit = wrd;
    } else if (wrd == W.BALANCE) {
      bal = wrd;
    } else if ((s16(first_) <= s16(0)) && ((wrd == W.BONGO || wrd == W.PONGO || wrd == W.PAULETTE) || (wrd == W.CLINT || wrd == W.ROGER || wrd == W.NANCY))) {
      person = wrd;
    }
    first_ = first_ - 1;
    ptr = ptr + P_LEXELEN;
  }
  if (!(bongo$ == 0) && (!(problem == 0) || !(addr == 0) || !(credit == 0) || !(money$ == 0) || !(form == 0) || !(bal == 0) || !(person == 0) || !(hold == 0))) {
    await PRINT_PICK_NEXT(BONGO_STUFF);
    tell("\n\n");
    (await ITALICIZE("Click!"));
    tell(" You hear a dialling tone, and hang up.\n");
    clearFlag(MACHINE, SEEN);
    await BANKSOUND_OFF();
    return true;
  } else if (!(form == 0)) {
    tell("\"You can obtain any forms you need at your local branch of Fillmore Fiduciary.\"\n");
  } else if (!(problem == 0)) {
    tell("\"Any difficulties you may be experiencing ");
    if (!(addr == 0)) {
      tell("with addressing ");
    } else if (!(credit == 0)) {
      tell("with credit cards ");
    }
    tell("should be addressed to our Customer Service Department.\"\n");
  } else if (!(addr == 0)) {
    tell("\"If you could hold for just a second, I'll look into that.\" ");
    g.HOLDING_FOR_PONGO$ = wrd;
    g.HOLDING_FOR_ADDRESS$ = true;
    await HOLD_BANK();
    return true;
  } else if (!(credit == 0)) {
    tell("\"Our Credit Card Department may be able to help.\"\n");
  } else if (!(person == 0)) {
    tell("\"Any comments you may have about bank personnel should be submitted on FFT Form 98/7/203/G/I/G/O. It's out of stock here, but I think the Auckland branch has some.\"\n");
  } else if (!(money$ == 0)) {
    tell("\"We're very fond of money here at Fillmore Fiduciary.\"\n");
  } else if (!(bal == 0)) {
    tell("\"We can't discuss account balances on the phone.\"\n");
  } else if (!(hold == 0)) {
    tell("\"No, ");
    (await ITALICIZE("we"));
    tell(" tell ");
    (await ITALICIZE("you"));
    tell(" when to hold.\"\n");
  } else {
    return false;
  }
  put(34022, 0, 3);
  return true;
}

