async function BANKSOUND_F(context = false) {
  let bsname = false, str = 0;
  if (hasFlag(BANKSOUND, NODESC)) {
    if (isVerb(V.PHONE)) {
      if (hasFlag(PAGE_2, SEEN)) {
        g.P_NUMBER = get(PHONE_NUMBERS, BANK_NUMBER_X);
        g.P_NUMBER = get(PHONE_NUMBERS, BANK_NUMBER);
        await PERFORM(V.PHONE, INTNUM);
      } else {
        await PERFORM(V.PHONE, ROOMS);
      }
      return true;
    } else {
      await REFERRING();
      return FATAL_VALUE;
    }
  } else if (eq(get(34022, 0), 0)) {
    tell("You're still on hold.\n");
    return true;
  } else if (context == M_WINNER) {
    g.WINNER = PLAYER;
    await PERFORM(V.ASK_ABOUT, BANKSOUND);
    return FATAL_VALUE;
  } else if (!(context == 0)) {
    return false;
  } else if (isVerb(V.TELL)) {
    if (str = await CHECK_OZ_ROYALTY(BANKSOUND, true)) {
      await CTHE_PRINT();
      tell(" whispers, \"", S(str), ".\"\n");
      return true;
    } else {
      return false;
    }
  } else if (!(g.NOW_PRSI$ == 0) && isVerb(V.GIVE)) {
    tell("Although ", D(g.PRSI), " would undoubtedly like having that, you can't really do much giving over the phone.\n");
    return true;
  } else if (isVerb(V.ASK_ABOUT, V.ASK_FOR)) {
    bsname = get(getPropAddr(BANKSOUND, P.SYNONYM), 0);
    if (bsname == W.PONGO) {
      tell("\"Squawk! Pongo want a dollar!\"\n");
    } else if (bsname == W.BONGO) {
      tell("\"Yap, yap, yap.\"\n");
    } else {
      await IN_CAPS(bsname);
      if (isVerb(V.HELLO, V.THANK)) {
        tell(" grunts in response.\n");
      } else {
        g.HOLDING_FOR_PONGO$ = bsname;
        tell(" says, \"I'll have to ask my supervisor. Please hold.\"\n\n");
        await HOLD_BANK();
      }
    }
    return FATAL_VALUE;
  } else if (isVerb(V.HANGUP)) {
    if (hasFlag(MACHINE, SEEN)) {
      clearFlag(MACHINE, SEEN);
      await BANKSOUND_OFF();
      tell("You slam the receiver down with a satisfying ");
      (await ITALICIZE("crash"));
      tell(S(PCR));
      await UPDATE_BP(-2);
    } else {
      tell("You aren't on the phone.\n");
    }
    return true;
  } else if ((await TOUCHING$()) || isVerb(V.EXAMINE)) {
    await CANT_FROM_HERE();
    return true;
  } else {
    return false;
  }
}

