async function TABLE_STATE(new_ = 2, bit = TABLE_MASK) {
  let data = (await GET_SEAT());
  if (new_ == 2) {
    if (!(btst(data, bit))) {
      return false;
    } else {
      return true;
    }
  } else if (new_ == 0) {
    return await SET_SEAT(data & ((bit ^ (-1)) << 16 >> 16));
  } else {
    return await SET_SEAT(data | bit);
  }
}

