async function POLICE_AREA(obj, tbl, where = PLAYER) {
  let nobj = 0, len = 0, n_ = 0;
  if (nobj = first(obj)) {
    if (tbl) {
      len = get(tbl, 0);
      tbl = tbl + 2;
    }
    loop1: for (;;) {
      if ((!tbl || !(inTable(nobj, tbl, len))) && !(hasFlag(nobj, PERSON)) && (nobj != PLAYER)) {
        obj = next(nobj);
        n_ = 1;
        if (where) {
          move(nobj, where);
        }
        nobj = obj;
      } else {
        nobj = next(nobj);
      }
      if (!nobj) {
        break loop1;
      }
    }
  }
  return n_;
}

