async function PERFORM_WITH_PLAYER(prsa, prso, prsi = false) {
  let owinner = g.WINNER, val = 0;
  g.WINNER = PLAYER;
  val = await PERFORM(prsa, prso, prsi);
  g.WINNER = owinner;
  return val;
}

