async function CHUTE_F() {
  if (isVerb(V.STINGLAI)) {
    return false;
  } else if (!(loc(CHUTE))) {
    if (hasFlag(g.HERE, IN_AIRPLANE)) {
      await CANT_SEE_ANY(CHUTE);
      return true;
    } else if (await TOUCHING$()) {
      tell(S(CANT), "reach ");
      await THE_PRINT(CHUTE);
      tell(S(PERIOD));
      return true;
    }
  } else if ((await NOUN_USED$(W.STRAP, W.STRAPS, W.LINE)) || (await NOUN_USED$(W.LINES, W.SHROUD))) {
    if (!(g.NOW_PRSI$ == 0)) {
    } else if (isVerb(V.EXAMINE, V.LOOK_ON)) {
      await CTHE_PRINT();
      tell("'s straps are ");
      if (g.HERE == OUTSIDE_PLANE) {
        tell("caught in the plane's hatch.\n");
      } else if (g.HERE == IN_AIR) {
        tell("fluttering in the breeze.\n");
      } else if (g.HERE == IN_TREE) {
        tell("hopelessly tangled in the tree.\n");
      } else if (hasFlag(CHUTE, WORN)) {
        tell("looped around your shoulders.\n");
      } else {
        tell("just sitting there.\n");
      }
      return true;
    } else if (isVerb(V.PULL, V.MOVE, V.PUSH, V.LOOSEN, V.ADJUST, V.LOWER, V.RAISE)) {
      if (g.HERE == IN_AIR) {
        tell("This has no useful effect.\n");
        return true;
      }
      tell("You struggle to ");
      printB(g.P_PRSA_WORD);
      tell(" the straps, but to no avail.\n");
      return true;
    } else if (isVerb(V.CUT) && !(g.PRSI == 0)) {
      if (!(hasFlag(g.PRSI, SHARPENED))) {
        tell("An ingenious idea. But you'll never sever those heavy-duty ", D(g.PRSO), " straps with ");
        await PRINTA(g.PRSI);
        tell(S(PERIOD));
        return true;
      }
      tell("You cleverly snip ");
      await THE_PRINT();
      tell("'s straps with ");
      await THEI_PRINT();
      if (await ON_PLANE$()) {
        tell(".\n\nCongratulations! You now get to observe the horns of a dilemma. Should you crash into the jungle with the ");
        await DPRINT(PLANE);
        tell(", and undoubtedly die, or jump out of the ");
        await DPRINT(PLANE);
        tell(" with a ruined parachute, and undoubtedly die? Fortunately, you'll have lots of time to weigh the pros and cons, because...");
        await JIGS_UP();
      } else {
        await LOOSEN_CHUTE();
      }
      return true;
    }
  }
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.PUT_ON, V.EMPTY_INTO)) {
      await IMPOSSIBLE();
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON, V.READ)) {
    if (!(loc(CHUTE))) {
      await CTHE_PRINT();
      tell(" is falling, somewhat faster than you. Perhaps you'll catch up with it in another life.\n");
      return true;
    } else if (g.HERE == OUTSIDE_PLANE) {
      await CTHE_PRINT();
      tell(" is strapped to your back, which is good, and caught in the emergency exit of the plane, which is bad.\n");
      return true;
    } else if (await CHUTE_OPEN$()) {
      tell("You just make out the words \"Chowmail Overnite\" written on ");
      await THE_PRINT();
      tell(S(PERIOD));
      return true;
    }
    tell("It's on your back, you know, so you can't tell much");
    if (loc(RIPCORD) == g.PRSO) {
      tell(". A red ripcord is fluttering nearby, though");
    }
    printS(PERIOD);
    return true;
  } else if (!(loc(CHUTE))) {
    tell(S(CANT), "reach ");
    await THE_PRINT();
    tell(S(PERIOD));
    return true;
  } else if (isVerb(V.TAKE_OFF, V.DROP, V.EXIT)) {
    if (hasFlag(CHUTE, WORN)) {
      tell("You cleverly slip ");
      await THE_PRINT();
      tell(" off your back");
      if (await ON_PLANE$()) {
        clearFlag(CHUTE, WORN);
        move(CHUTE, PLAYER);
        tell(S(PERIOD));
      } else {
        await LOOSEN_CHUTE();
      }
      return true;
    } else if (isVerb(V.DROP)) {
      return false;
    } else {
      tell("You aren't wearing ");
      await THE_PRINT();
      tell(S(PERIOD));
      return true;
    }
  } else if (isVerb(V.OPEN, V.UNFOLD)) {
    await OPEN_CHUTE();
    return true;
  } else if (isVerb(V.CLOSE, V.FOLD)) {
    if (hasFlag(g.PRSO, OPENED)) {
      tell("Easier said than done.\n");
    } else {
      await ALREADY_CLOSED();
    }
    return true;
  } else if (isVerb(V.WEAR) && (g.HERE == IN_AIR) && !g.CHUTE_SCORED$ && !(hasFlag(g.PRSO, WORN))) {
    await V_WEAR();
    await UPDATE_SCORE(1);
    g.CHUTE_SCORED$ = true;
    return true;
  } else {
    return false;
  }
}

async function LOOSEN_CHUTE() {
  tell(", and immediately plummet ");
  remove(CHUTE);
  if (g.HERE == OUTSIDE_PLANE) {
    tell("away from the plane.\n");
    await TO_IN_AIR();
  } else {
    tell("towards the ground below.\n");
    if (g.HERE == IN_AIR) {
      await HIT_GROUND();
    } else {
      await GOTO(IN_POT, false);
      crlf();
      (await ITALICIZE("Splash"));
      tell("!\n\n");
      await V_LOOK();
      await THIS_IS_IT(NATIVES);
      if (!(await META_IN$(RECIPE, g.HERE)) || !(await META_IN$(COMPUTER, g.HERE))) {
        await NATIVES_EAT_YOU();
      } else {
        await UPDATE_SCORE(1);
      }
    }
  }
  return true;
}

async function OPEN_CHUTE() {
  if (await ON_PLANE$()) {
    tell("The size of even a modest parachute is fairly impressive when compared to the cramped quarters inside an ");
    await DPRINT(PLANE);
    tell(". By the time you manage to untangle yourself (and several other passengers) from the various straps, shrouds, canopies, and cords, it's too late to jump: the ");
    await DPRINT(PLANE);
    tell(" has crashed into the jungle.");
    await JIGS_UP();
    return true;
  } else if (await CHUTE_OPEN$()) {
    tell("You yank on ");
    await THE_PRINT(RIPCORD);
    tell(" again, but as ");
    await THE_PRINT(CHUTE);
    tell(" is already deployed, nothing happens.\n");
    return true;
  } else if (g.HERE == OUTSIDE_PLANE) {
    tell("Things were bad enough with your ", D(CHUTE), " straps caught in the hatch. Pulling ");
    await THE_PRINT(RIPCORD);
    tell(", as you might well have expected, has added the complication of a deployed ", D(CHUTE), " as well. The various straps, cords and other ", D(CHUTE), " paraphernalia, each going its own merry way, send you flying in a number of very unpleasant pieces.");
    await JIGS_UP();
    return true;
  } else if (!(hasFlag(CHUTE, WORN))) {
    tell("When a parachute opens, it wants to decelerate rather rapidly. That's why people wear them -- when they're falling out of airplanes, they normally want to decelerate as well. Unfortunately, you've just encountered various of the laws of physics, which result in the chute decelerating and ripping itself out of your hands. The sight of the canopy billowing high above you is a great comfort as you plunge to your death.");
    await JIGS_UP();
    return true;
  }
  clearFlag(CHUTE, TRANSPARENT);
  setFlag(CHUTE, OPENED);
  await CTHE_PRINT(CHUTE);
  tell(" opens. You are floating serenely through a clear blue sky which is unfortunately totally obscured by thick black clouds.\n");
  return true;
}

async function RIPCORD_F() {
  if (!(loc(CHUTE) == PLAYER)) {
    tell("You'd better grow longer arms if you're going to reach ");
    await THE_PRINT(RIPCORD);
    tell(" from here.\n");
    return true;
  } else if (!(g.NOW_PRSI$ == 0)) {
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON)) {
    await CTHE_PRINT();
    if (hasFlag(CHUTE, OPENED)) {
      tell(" you've pulled");
    }
    tell(" is dangling from ");
    await THE_PRINT(CHUTE);
    tell(S(PERIOD));
    return true;
  } else if (isVerb(V.TAKE, V.PULL, V.USE, V.PLAY)) {
    await OPEN_CHUTE();
    return true;
  } else {
    return false;
  }
}

